"""Exact native cleanup result predicates; never supplies missing runtime facts."""
def install_plan(C,value,index):
 C.need(value.get('status')=='PLANNED' and value.get('applied')=='NOT_APPLIED' and value.get('installer_authority') is False and value.get('synthetic') is True,'authenticated readonly fixture plan required')
 plan=value.get('plan',{});names={'cachy-asahi-apps':'0.1.0-5','cachy-asahi-repository-runtime':'0.1.0-1'}
 C.need(plan.get('operation')=='install' and plan.get('requested_applications')==['apps'] and plan.get('requested_packages')==['cachy-asahi-apps'] and all(plan.get(k)==[] for k in ('upgrades','removals','conflicts','unchanged_selected')),'only exact Apps dependency install allowed')
 rows=plan.get('additions',[]);C.need(type(rows) is list and len(rows)==2 and {r['name']:r['version'] for r in rows}==names,'exact authenticated Apps+Runtime additions required before commit')
 byname={r['name']:r for r in rows};relation='cachy-asahi-repository-runtime=0.1.0-1'
 C.need(relation in byname['cachy-asahi-apps'].get('depend',[]) and plan.get('dependencies')==[dict(package='cachy-asahi-repository-runtime',required_by='cachy-asahi-apps',dependency=relation)],'actual signed Apps Runtime dependency required')
 for name,row in byname.items():
  native=index['packages'][name];C.need(native['version']==names[name] and row.get('source')=='signed-release' and row.get('release_archive_sha256')==native['files']['a']['sha256'],'original accepted pair archive binding required')
 return dict(status='EXACT_AUTHENTICATED_APPS_RUNTIME_INSTALL_PLAN',plan_sha256=C.sha(C.encoded(value)),additions=names,dependency=relation,archives={n:r['release_archive_sha256'] for n,r in byname.items()})

def result(C,value):
 C.need(value.get('status')=='PASS_NATIVE574_SELECTED_ORPHAN_CLEANUP' and value.get('base_count')==574 and value.get('counts')==[576,575] and value.get('selected')==['cachy-asahi-apps'],'genuine selected Apps matrix required')
 C.need(value.get('source_preserved') is True and value.get('user_trust_protected_preserved') is True and value.get('workspaces_disposed') is True and value.get('hardware')=='NOT_RUN' and value.get('rollback')=='NOT_CLAIMED' and value.get('interrupted_copy')=='NOT_RUN_SEPARATE_ACTOR_REQUIRED','complete native original source/preservation/disposal required')
 cases=value.get('cases',{});C.need(set(cases)=={'noop','cancel','foreign_lock','normal','stale'} and cases['noop'].get('status')=='NOT_APPLIED_NO_SELECTION' and cases['cancel'].get('status')=='CANCELLED_NOT_APPLIED' and all(cases[n].get('status')=='FAIL' for n in ('foreign_lock','stale')),'all explicit no-op/cancel/refusal cases required')
 preserve=value.get('case_preservation',{});C.need(preserve.get('qualification')=='FULL_ROOT_DIGEST_EQUALITY_NOT_COMMIT_EVENT_PROOF','qualified complete refusal preservation required')
 for key in ('noop_cancel_foreign','stale'):
  row=preserve.get(key,{});C.need(row.get('before')==row.get('after') and set(row.get('before',{}))=={'tree_sha256','database_sha256','packages_sha256','inventory_sha256'} and all(__import__('re').fullmatch('[a-f0-9]{64}',v) for v in row['before'].values()),'refusal/cancel/no-op full root bytes differ')
 graph=value.get('actual_reason_graph',{});cache=graph.get('cachy-asahi-apps',{});runtime=graph.get('cachy-asahi-repository-runtime',{});C.need(cache.get('candidate') is True and cache.get('reason')=='dependency' and cache.get('required_by')==cache.get('optional_required_by')==[] and runtime.get('reason')=='dependency' and runtime.get('required_by')==['cachy-asahi-apps'],'actual dependency leaf/needed Runtime graph required')
 normal=cases['normal'];C.need(normal.get('status')=='PASS_SELECTED_CATALOG_ORPHAN_REMOVAL_IN_OWNED_COPY' and normal.get('prepared_add')=={} and normal.get('prepared_remove')=={'cachy-asahi-apps':'0.1.0-5'} and normal.get('commit_started') is True and normal.get('packages_committed') is True and normal.get('dependency_checks')=='ORDINARY_LIBALPM','one exact ordinary ALPM removal commit required')
 C.need(normal.get('selected')==['cachy-asahi-apps'] and set(normal.get('retained_matching_signed_cache',{}))=={'cachy-asahi-apps'},'exact authenticated matching rollback cache required')
 C.need(value.get('dependency_reason_readback')=='ACTUAL_PUBLIC_ALPM_ALLDEPS_AND_ORPHANS2_GRAPH' and value.get('security_capabilities')=='EXACT_SOURCE_MAP_PRESERVED','actual reason graph and capability proof required')
 C.need(len(value.get('transactions',[]))==2 and value['transactions'][1]==normal and value['transactions'][0].get('prepared_add')=={'cachy-asahi-apps':'0.1.0-5','cachy-asahi-repository-runtime':'0.1.0-1'},'exact dependency install and selected removal required')
 precommit=value.get('precommit_install_plan',{});C.need(precommit.get('status')=='EXACT_AUTHENTICATED_APPS_RUNTIME_INSTALL_PLAN' and precommit.get('additions')=={'cachy-asahi-apps':'0.1.0-5','cachy-asahi-repository-runtime':'0.1.0-1'} and precommit.get('dependency')=='cachy-asahi-repository-runtime=0.1.0-1' and set(precommit.get('archives',{}))=={'cachy-asahi-apps','cachy-asahi-repository-runtime'} and all(__import__('re').fullmatch('[a-f0-9]{64}',p) for p in precommit['archives'].values()) and precommit.get('plan_sha256')==value['transactions'][0].get('plan_sha256') and __import__('re').fullmatch('[a-f0-9]{64}',precommit.get('plan_sha256','')),'original qualified plan must precede and bind actual install')
 after=value.get('after_reason_graph',{});runtime=after.get('cachy-asahi-repository-runtime',{});C.need('cachy-asahi-apps' not in after and len(after)==575 and runtime.get('reason')=='dependency' and runtime.get('candidate') is True and runtime.get('required_by')==runtime.get('optional_required_by')==[],'actual now-orphan Runtime must remain after Apps removal')
 for row in value['transactions']:
  closure=row.get('full574_closure',{});C.need(closure.get('status')=='PASS-recorded-state-preserved' and closure.get('main_cache')=='RAW_EQUAL' and closure.get('auxiliary_transition')=={'kind':'RAW_EQUAL'} and closure.get('security_capabilities')=='EXACT_SOURCE_MAP_PRESERVED' and closure.get('source_capabilities_sha256')==value['source_capabilities_sha256'] and row.get('cleanup')=='OWNED_WORKSPACE_TEMP_AND_ALPM_HANDLE_LOCK_RELEASED','original full574 aux/capability/source cleanup proof required')
 return value
